#include "config.hpp"
#include <cctype>
#include <sstream>
#include <stdexcept>
#include "files.hpp"

namespace {
	[[noreturn]] void fail(std::string const& name, size_t line, std::string const& what)
	{
		throw std::runtime_error(name + ":" + std::to_string(line) + ": " + what);
	}

	std::string trim(std::string text)
	{
		size_t begin = 0;
		while ((begin < text.size()) && std::isspace((unsigned char)text[begin])) {
			begin++;
		}
		size_t end = text.size();
		while ((end > begin) && std::isspace((unsigned char)text[end - 1])) {
			end--;
		}
		return text.substr(begin, end - begin);
	}

	struct json_reader {
		std::string const& text;
		std::string const& name;
		size_t             at   = 0;
		size_t             line = 1;

		void skip()
		{
			while (at < text.size()) {
				if (text[at] == '\n') {
					line++;
				} else if (!std::isspace((unsigned char)text[at])) {
					break;
				}
				at++;
			}
		}

		bool eat(char c)
		{
			skip();
			if ((at < text.size()) && (text[at] == c)) {
				at++;
				return true;
			}
			return false;
		}

		std::string string()
		{
			skip();
			if ((at >= text.size()) || (text[at] != '"')) {
				fail(name, line, "expected a string");
			}
			at++;
			std::string out;
			while (true) {
				if (at >= text.size()) {
					fail(name, line, "the string is not closed");
				}
				char c = text[at++];
				if (c == '"') {
					return out;
				}
				if (c != '\\') {
					out += c;
					continue;
				}
				if (at >= text.size()) {
					fail(name, line, "the string is not closed");
				}
				switch (char e = text[at++]) {
				case 'n':
					out += '\n';
					break;
				case 't':
					out += '\t';
					break;
				case 'r':
					out += '\r';
					break;
				case 'b':
				case 'f':
					break;
				case 'u': {
					if (at + 4 > text.size()) {
						fail(name, line, "bad \\u escape");
					}
					unsigned code = (unsigned)std::stoul(text.substr(at, 4), nullptr, 16);
					at += 4;
					if (code < 0x80) {
						out += char(code);
					} else if (code < 0x800) {
						out += char(0xC0 | (code >> 6));
						out += char(0x80 | (code & 0x3F));
					} else {
						out += char(0xE0 | (code >> 12));
						out += char(0x80 | ((code >> 6) & 0x3F));
						out += char(0x80 | (code & 0x3F));
					}
					break;
				}
				default:
					out += e; // \" \\ \/
					break;
				}
			}
		}
	};
} // namespace

std::string blitz::tools::normalize_key(std::string key)
{
	for (auto& c : key) {
		c = (c == '-') ? '_' : char(std::tolower((unsigned char)c));
	}
	return key;
}

std::optional<std::filesystem::path> blitz::tools::find_config(std::filesystem::path directory, std::vector<std::string> const& names)
{
	std::error_code ec;
	directory = std::filesystem::absolute(directory, ec).lexically_normal();
	while (!directory.empty()) {
		for (auto const& name : names) {
			auto candidate = directory / name;
			if (std::filesystem::is_regular_file(candidate, ec)) {
				return candidate;
			}
		}
		auto parent = directory.parent_path();
		if (parent == directory) {
			break;
		}
		directory = parent;
	}
	return std::nullopt;
}

blitz::tools::settings blitz::tools::load_config(std::filesystem::path const& file)
{
	return parse_config(read_file(file), file.generic_string());
}

blitz::tools::settings blitz::tools::parse_config(std::string const& raw, std::string const& name)
{
	std::string text = raw;
	if (text.compare(0, 3, "\xEF\xBB\xBF") == 0) {
		text.erase(0, 3);
	}
	settings out;

	if (trim(text).empty()) {
		return out;
	}

	if (trim(text)[0] == '{') {
		json_reader json{ text, name };
		json.eat('{');
		if (!json.eat('}')) {
			do {
				std::string key = json.string();
				if (!json.eat(':')) {
					fail(name, json.line, "expected ':' after \"" + key + "\"");
				}
				json.skip();
				std::string value;
				if ((json.at < text.size()) && (text[json.at] == '"')) {
					value = json.string();
				} else {
					// Number, true, false: Whatever is up to the next , or }
					size_t start = json.at;
					while ((json.at < text.size()) && (text[json.at] != ',') && (text[json.at] != '}') && (text[json.at] != '\n')) {
						json.at++;
					}
					value = trim(text.substr(start, json.at - start));
					if (value.empty() || (value[0] == '{') || (value[0] == '[') || (value == "null")) {
						fail(name, json.line, "\"" + key + "\" needs a string, a number or true/false");
					}
				}
				out.emplace_back(normalize_key(key), value);
			} while (json.eat(','));
			if (!json.eat('}')) {
				fail(name, json.line, "expected ',' or '}'");
			}
		}
		json.skip();
		if (json.at < text.size()) {
			fail(name, json.line, "unexpected text after the closing '}'");
		}
		return out;
	}

	std::istringstream stream(text);
	std::string        line;
	size_t             number = 0;
	while (std::getline(stream, line)) {
		number++;
		line = trim(line);
		if (line.empty() || (line[0] == '#') || (line[0] == ';')) {
			continue;
		}
		size_t eq = line.find('=');
		if (eq == std::string::npos) {
			fail(name, number, "expected 'key = value'");
		}
		std::string key   = trim(line.substr(0, eq));
		std::string value = trim(line.substr(eq + 1));
		if (key.empty()) {
			fail(name, number, "expected a key before '='");
		}
		if ((value.size() >= 2) && (value.front() == '"') && (value.back() == '"')) {
			value = value.substr(1, value.size() - 2);
		}
		out.emplace_back(normalize_key(key), value);
	}
	return out;
}
